import React, { useEffect } from "react";
import { graphql, type HeadFC, type PageProps } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/Layout";
import I18nHeadProvider from "../components/I18nHeadProvider";
import SEO from "../components/seo";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import images from "../images";
import {
  buildBreadcrumbListSchema,
  localizeSitePath,
} from "../utils/structuredData";

const info: Company = data[0];

type ListItem = { item: string };

const PrivacyPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const cookiesItems = t("privacy.sections.cookies.items", {
    returnObjects: true,
  }) as ListItem[];
  const analyticsItems = t("privacy.sections.analytics.items", {
    returnObjects: true,
  }) as ListItem[];
  const choicesItems = t("privacy.sections.choices.items", {
    returnObjects: true,
  }) as ListItem[];
  const contactItems = t("privacy.sections.contact.items", {
    returnObjects: true,
  }) as ListItem[];

  return (
    <Layout data={info}>
      <section className="py-10 sm:py-14">
        <div className="mx-auto w-full max-w-4xl px-4">
          <header className="rounded-3xl border border-white/10 bg-primary/70 p-6 sm:p-8">
            <p className="text-sm uppercase tracking-[0.16em] text-purplelight">
              {t("privacy.hero.eyebrow")}
            </p>
            <h1 className="mt-3 text-3xl sm:text-5xl poppins-bold text-light">
              {t("privacy.hero.title")}
            </h1>
            <p className="mt-4 text-base sm:text-lg text-light/85">
              {t("privacy.hero.subtitle")}
            </p>
            <p className="mt-4 text-sm text-light/65">
              {t("privacy.hero.updated")}
            </p>
          </header>

          <div className="mt-8 space-y-5">
            <section className={styles.card}>
              <h2 className={styles.heading}>{t("privacy.sections.overview.title")}</h2>
              <p className={styles.copy}>{t("privacy.sections.overview.text")}</p>
            </section>

            <section className={styles.card}>
              <h2 className={styles.heading}>{t("privacy.sections.cookies.title")}</h2>
              <p className={styles.copy}>{t("privacy.sections.cookies.text")}</p>
              <ul className={styles.list}>
                {cookiesItems.map((entry, index) => (
                  <li key={`${entry.item}-${index}`}>{entry.item}</li>
                ))}
              </ul>
            </section>

            <section className={styles.card}>
              <h2 className={styles.heading}>{t("privacy.sections.analytics.title")}</h2>
              <p className={styles.copy}>{t("privacy.sections.analytics.text")}</p>
              <ul className={styles.list}>
                {analyticsItems.map((entry, index) => (
                  <li key={`${entry.item}-${index}`}>{entry.item}</li>
                ))}
              </ul>
            </section>

            <section className={styles.card}>
              <h2 className={styles.heading}>{t("privacy.sections.choices.title")}</h2>
              <p className={styles.copy}>{t("privacy.sections.choices.text")}</p>
              <ul className={styles.list}>
                {choicesItems.map((entry, index) => (
                  <li key={`${entry.item}-${index}`}>{entry.item}</li>
                ))}
              </ul>
            </section>

            <section className={styles.card}>
              <h2 className={styles.heading}>{t("privacy.sections.contact.title")}</h2>
              <p className={styles.copy}>{t("privacy.sections.contact.text")}</p>
              <ul className={styles.list}>
                {contactItems.map((entry, index) => (
                  <li key={`${entry.item}-${index}`}>{entry.item}</li>
                ))}
              </ul>
            </section>
          </div>
        </div>
      </section>
    </Layout>
  );
};

const PrivacyHeadContent: React.FC = () => {
  const { t } = useTranslation();
  const { language, defaultLanguage } = useI18next();
  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home") as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("privacy.hero.title") as string,
      path: localizeSitePath("/privacy/", language, defaultLanguage),
    },
  ]);

  return (
    <SEO
      data={info}
      titleKey="privacy.metaTitle"
      descriptionKey="privacy.metaDescription"
      pathname="/privacy/"
      schemaType="ProfessionalService"
      pageSchemaType="WebPage"
      additionalSchemas={breadcrumbSchema ? [breadcrumbSchema] : undefined}
    />
  );
};

export const Head: HeadFC = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <PrivacyHeadContent />
  </I18nHeadProvider>
);

export default PrivacyPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  card: "rounded-3xl border border-white/10 bg-darkBg/50 p-6 sm:p-8",
  heading: "text-2xl sm:text-3xl poppins-regular text-verde",
  copy: "mt-3 text-sm sm:text-base leading-relaxed text-light/85",
  list: "mt-4 list-disc space-y-2 pl-5 text-sm sm:text-base text-light/80",
};
